        for c in range(cols):
            if grid[r][c] == 2:
                twos.append((r, c))

    if not twos:
        return [row[:] for row in grid]

    # Pattern: for each 2, place all special values at their relative positions
    # First find where each special is relative to the first 2
    first_tr, first_tc = twos[0]
    relative_positions = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and grid[r][c] != 2:
                relative_positions.append((grid[r][c], r - first_tr, c - first_tc))

